#!/usr/bin/env python3
"""
Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)
Report Generation Script
"""

import pandas as pd
import numpy as np
from datetime import datetime
import math

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# ============ DATA PREPARATION ============
df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
df['User Rating'] = pd.to_numeric(df['User Rating'], errors='coerce')
df['Reviews'] = pd.to_numeric(df['Reviews'], errors='coerce')
df['Year'] = pd.to_numeric(df['Year'], errors='coerce')

# ============ KPI CALCULATIONS ============

# Basic counts
total_records = len(df)
unique_books = df['Name'].nunique()
year_range = f"{df['Year'].min()}–{df['Year'].max()}"

# Genre split
genre_counts = df['Genre'].value_counts()
fiction_count = genre_counts.get('Fiction', 0)
nonfiction_count = genre_counts.get('Non Fiction', 0)

# Overall averages
avg_rating = df['User Rating'].mean()
avg_price = df['Price'].mean()
avg_reviews = df['Reviews'].mean()

# Fiction stats
fiction_df = df[df['Genre'] == 'Fiction']
fiction_avg_rating = fiction_df['User Rating'].mean()
fiction_avg_price = fiction_df['Price'].mean()
fiction_avg_reviews = fiction_df['Reviews'].mean()

# Non-Fiction stats
nonfiction_df = df[df['Genre'] == 'Non Fiction']
nonfiction_avg_rating = nonfiction_df['User Rating'].mean()
nonfiction_avg_price = nonfiction_df['Price'].mean()
nonfiction_avg_reviews = nonfiction_df['Reviews'].mean()

# Pearson correlation coefficient
pearson_corr = df['Price'].corr(df['User Rating'])

# Year-over-year stats
yearly_stats = df.groupby('Year').agg({
    'User Rating': 'mean',
    'Price': 'mean',
    'Reviews': 'mean',
    'Name': 'count'
}).rename(columns={'Name': 'Book Count'}).reset_index()

yearly_fiction = fiction_df.groupby('Year').agg({
    'User Rating': 'mean',
    'Price': 'mean'
}).reset_index()
yearly_fiction.columns = ['Year', 'Fiction_Rating', 'Fiction_Price']

yearly_nonfiction = nonfiction_df.groupby('Year').agg({
    'User Rating': 'mean',
    'Price': 'mean'
}).reset_index()
yearly_nonfiction.columns = ['Year', 'Nonfiction_Rating', 'Nonfiction_Price']

yearly_combined = yearly_stats.merge(yearly_fiction, on='Year').merge(yearly_nonfiction, on='Year')

# Top authors by bestseller frequency
author_counts = df['Author'].value_counts().head(15)
top_authors_data = []
for author, count in author_counts.items():
    author_df = df[df['Author'] == author]
    top_authors_data.append({
        'author': author,
        'appearances': count,
        'avg_rating': author_df['User Rating'].mean(),
        'avg_price': author_df['Price'].mean(),
        'avg_reviews': author_df['Reviews'].mean()
    })

# Price segment analysis
price_bins = [0, 10, 20, 30, 50, 100, float('inf')]
price_labels = ['$0-10', '$10-20', '$20-30', '$30-50', '$50-100', '$100+']
df['Price_Segment'] = pd.cut(df['Price'], bins=price_bins, labels=price_labels)

price_segment_stats = df.groupby('Price_Segment').agg({
    'User Rating': 'mean',
    'Reviews': 'mean',
    'Name': 'count'
}).rename(columns={'Name': 'Count'}).reset_index()

# ============ SVG CHART GENERATION ============

def generate_line_chart_svg(data_points, width=600, height=300, title="", x_label="", y_label="", colors=None):
    """Generate SVG line chart"""
    if not data_points:
        return ""

    padding = {'top': 30, 'right': 30, 'bottom': 50, 'left': 60}
    chart_width = width - padding['left'] - padding['right']
    chart_height = height - padding['top'] - padding['bottom']

    # Extract data
    all_values = []
    all_labels = []
    for series in data_points:
        all_values.extend(series.get('values', []))
        all_labels.extend(series.get('labels', []))

    if not all_values:
        return ""

    min_val = min(all_values)
    max_val = max(all_values)
    val_range = max_val - min_val if max_val != min_val else 1

    # Generate paths for each series
    paths = ""
    dots = ""
    legend_items = ""

    for idx, series in enumerate(data_points):
        values = series.get('values', [])
        labels = series.get('labels', [])
        color = (colors and colors[idx]) or f"hsl({idx * 120}, 70%, 50%)"

        if not values:
            continue

        points = []
        for i, val in enumerate(values):
            x = padding['left'] + (i / (len(values) - 1)) * chart_width if len(values) > 1 else padding['left'] + chart_width / 2
            y = padding['top'] + (1 - (val - min_val) / val_range) * chart_height
            points.append(f"{x:.1f},{y:.1f}")

        if points:
            paths += f'<polyline points="{" ".join(points)}" fill="none" stroke="{color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>'
            for i, val in enumerate(values):
                x = padding['left'] + (i / (len(values) - 1)) * chart_width if len(values) > 1 else padding['left'] + chart_width / 2
                y = padding['top'] + (1 - (val - min_val) / val_range) * chart_height
                dots += f'<circle cx="{x:.1f}" cy="{y:.1f}" r="4" fill="{color}"/>'

        legend_items += f'<rect x="{width - 120}" y="{padding['top'] + idx * 25}" width="15" height="15" fill="{color}"/><text x="{width - 100}" y="{padding['top'] + idx * 25 + 12}" font-size="12">{series.get("name", "")}</text>'

    # X-axis labels
    x_labels = ""
    label_values = labels
    for i, label in enumerate(label_values):
        x = padding['left'] + (i / (len(label_values) - 1)) * chart_width if len(label_values) > 1 else padding['left'] + chart_width / 2
        x_labels += f'<text x="{x:.1f}" y="{height - 15}" font-size="11" text-anchor="middle">{label}</text>'

    # Y-axis labels
    y_labels = ""
    for i in range(5):
        val = min_val + (val_range * i / 4)
        y = padding['top'] + (1 - i / 4) * chart_height
        y_labels += f'<text x="{padding['left'] - 10}" y="{y + 4}" font-size="11" text-anchor="end">{val:.2f}</text>'

    svg = f'''<svg width="{width}" height="{height}" viewBox="0 0 {width} {height}">
        <style>
            text {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; fill: #555; }}
        </style>
        <line x1="{padding['left']}" y1="{padding['top']}" x2="{padding['left']}" y2="{height - padding['bottom']}" stroke="#ddd"/>
        <line x1="{padding['left']}" y1="{height - padding['bottom']}" x2="{width - padding['right']}" y2="{height - padding['bottom']}" stroke="#ddd"/>
        {y_labels}
        {x_labels}
        {paths}
        {dots}
        {legend_items}
        <text x="{width/2}" y="20" font-size="14" font-weight="600" text-anchor="middle">{title}</text>
        <text x="{width/2}" y="{height - 5}" font-size="11" text-anchor="middle">{x_label}</text>
    </svg>'''

    return svg

def generate_scatter_svg(x_data, y_data, width=600, height=400, title="", x_label="", y_label=""):
    """Generate SVG scatter plot for price-rating correlation"""
    padding = {'top': 40, 'right': 40, 'bottom': 60, 'left': 70}
    chart_width = width - padding['left'] - padding['right']
    chart_height = height - padding['top'] - padding['bottom']

    min_x, max_x = min(x_data), max(x_data)
    min_y, max_y = min(y_data), max(y_data)
    x_range = max_x - min_x if max_x != min_x else 1
    y_range = max_y - min_y if max_y != min_y else 1

    # Fiction and Non-Fiction points
    fiction_x = fiction_df['Price'].tolist()
    fiction_y = fiction_df['User Rating'].tolist()
    nonfiction_x = nonfiction_df['Price'].tolist()
    nonfiction_y = nonfiction_df['User Rating'].tolist()

    fiction_points = []
    for x, y in zip(fiction_x, fiction_y):
        px = padding['left'] + (x - min_x) / x_range * chart_width
        py = height - padding['bottom'] - (y - min_y) / y_range * chart_height
        fiction_points.append(f"{px:.1f},{py:.1f}")

    nonfiction_points = []
    for x, y in zip(nonfiction_x, nonfiction_y):
        px = padding['left'] + (x - min_x) / x_range * chart_width
        py = height - padding['bottom'] - (y - min_y) / y_range * chart_height
        nonfiction_points.append(f"{px:.1f},{py:.1f}")

    # Create point elements
    fiction_circles = '<circle cx="{px}" cy="{py}" r="5" fill="#3498db" opacity="0.6"/>'
    nonfiction_circles = '<circle cx="{px}" cy="{py}" r="5" fill="#e74c3c" opacity="0.6"/>'

    fiction_html = "".join([f'<circle cx="{p.split(",")[0]}" cy="{p.split(",")[1]}" r="5" fill="#3498db" opacity="0.6"/>' for p in fiction_points])
    nonfiction_html = "".join([f'<circle cx="{p.split(",")[0]}" cy="{p.split(",")[1]}" r="5" fill="#e74c3c" opacity="0.6"/>' for p in nonfiction_points])

    # X-axis labels
    x_labels = ""
    for i in range(6):
        val = min_x + (x_range * i / 5)
        x = padding['left'] + (i / 5) * chart_width
        x_labels += f'<text x="{x:.1f}" y="{height - 30}" font-size="11" text-anchor="middle">${val:.0f}</text>'

    # Y-axis labels
    y_labels = ""
    for i in range(5):
        val = min_y + (y_range * i / 4)
        y = height - padding['bottom'] - (i / 4) * chart_height
        y_labels += f'<text x="{padding['left'] - 10}" y="{y + 4}" font-size="11" text-anchor="end">{val:.1f}</text>'

    # Legend
    legend = f'''<rect x="{width - 150}" y="{padding['top']}" width="15" height="15" fill="#3498db"/><text x="{width - 130}" y="{padding['top'] + 12}" font-size="12">Fiction</text>
