def generate_bar_chart_svg(data, width=500, height=300, title="", horizontal=False):
    """Generate SVG bar chart"""
    padding = {'top': 40, 'right': 30, 'bottom': 60, 'left': 60}
    chart_width = width - padding['left'] - padding['right']
    chart_height = height - padding['top'] - padding['bottom']

    n_bars = len(data)
    bar_width = chart_width / n_bars * 0.7
    bar_gap = chart_width / n_bars * 0.3

    max_val = max([d['value'] for d in data]) if data else 1

    bars = ""
    labels = ""
    values_text = ""

    for i, d in enumerate(data):
        if horizontal:
            bar_height = d['value'] / max_val * chart_height
            x = padding['left']
            y = padding['top'] + i * (chart_height / n_bars) + bar_gap/2
            bars += f'<rect x="{x}" y="{y}" width="{bar_height}" height="{bar_width}" fill="{d.get("color", "#3498db")}" rx="3"/>'
            labels += f'<text x="{x - 10}" y="{y + bar_width/2 + 4}" font-size="11" text-anchor="end">{d["label"]}</text>'
            values_text += f'<text x="{x + bar_height + 5}" y="{y + bar_width/2 + 4}" font-size="11">{d["value"]:.2f}</text>'
        else:
            bar_height = d['value'] / max_val * chart_height
            x = padding['left'] + i * (chart_width / n_bars) + bar_gap/2
            y = height - padding['bottom'] - bar_height
            bars += f'<rect x="{x}" y="{y}" width="{bar_width}" height="{bar_height}" fill="{d.get("color", "#3498db")}" rx="3"/>'
            labels += f'<text x="{x + bar_width/2}" y="{height - 30}" font-size="11" text-anchor="middle">{d["label"]}</text>'
            values_text += f'<text x="{x + bar_width/2}" y="{y - 5}" font-size="11" text-anchor="middle">{d["value"]:.2f}</text>'

    svg = f'''<svg width="{width}" height="{height}" viewBox="0 0 {width} {height}">
        <style>
            text {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; fill: #555; }}
        </style>
        <line x1="{padding['left']}" y1="{height - padding['bottom']}" x2="{width - padding['right']}" y2="{height - padding['bottom']}" stroke="#ccc"/>
        <line x1="{padding['left']}" y1="{padding['top']}" x2="{padding['left']}" y2="{height - padding['bottom']}" stroke="#ccc"/>
        {bars}
        {labels}
        {values_text}
        <text x="{width/2}" y="22" font-size="14" font-weight="600" text-anchor="middle">{title}</text>
    </svg>'''

    return svg

def generate_comparison_bar_svg(categories, series_data, width=600, height=350, title=""):
    """Generate grouped bar chart for comparisons"""
    padding = {'top': 50, 'right': 30, 'bottom': 60, 'left': 60}
    chart_width = width - padding['left'] - padding['right']
    chart_height = height - padding['top'] - padding['bottom']

    n_categories = len(categories)
    n_series = len(series_data)
    group_width = chart_width / n_categories
    bar_width = group_width / (n_series + 1) * 0.8

    max_val = max([max(s['values']) for s in series_data]) if series_data else 1

    all_bars = ""
    all_labels = ""
    legend_items = ""

    colors = ["#3498db", "#e74c3c", "#2ecc71", "#f39c12"]

    for cat_idx, category in enumerate(categories):
        for s_idx, series in enumerate(series_data):
            bar_height = series['values'][cat_idx] / max_val * chart_height
            x = padding['left'] + cat_idx * group_width + (s_idx + 0.5) * bar_width
            y = height - padding['bottom'] - bar_height
            all_bars += f'<rect x="{x}" y="{y}" width="{bar_width}" height="{bar_height}" fill="{colors[s_idx % len(colors)]}" rx="2"/>'

        all_labels += f'<text x="{padding['left'] + cat_idx * group_width + group_width/2}" y="{height - 35}" font-size="12" text-anchor="middle">{category}</text>'

    for s_idx, series in enumerate(series_data):
        legend_items += f'<rect x="{width - 150}" y="{padding["top"] - 30 + s_idx * 22}" width="15" height="15" fill="{colors[s_idx % len(colors)]}"/><text x="{width - 130}" y="{padding["top"] - 30 + s_idx * 22 + 12}" font-size="12">{series["name"]}</text>'

    svg = f'''<svg width="{width}" height="{height}" viewBox="0 0 {width} {height}">
        <style>
            text {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; fill: #555; }}
        </style>
        <line x1="{padding['left']}" y1="{height - padding['bottom']}" x2="{width - padding['right']}" y2="{height - padding['bottom']}" stroke="#ccc"/>
        <line x1="{padding['left']}" y1="{padding['top']}" x2="{padding['left']}" y2="{height - padding['bottom']}" stroke="#ccc"/>
        {all_bars}
        {all_labels}
        {legend_items}
        <text x="{width/2}" y="22" font-size="14" font-weight="600" text-anchor="middle">{title}</text>
    </svg>'''

    return svg

