import pandas as pd
import numpy as np
from datetime import datetime
import math

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# ============ DATA PREPARATION ============
df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
df['User Rating'] = pd.to_numeric(df['User Rating'], errors='coerce')
df['Reviews'] = pd.to_numeric(df['Reviews'], errors='coerce')
df['Year'] = pd.to_numeric(df['Year'], errors='coerce')

# ============ KPI CALCULATIONS ============

# Basic counts
total_records = len(df)
unique_books = df['Name'].nunique()
year_range = f"{df['Year'].min()}–{df['Year'].max()}"

# Genre split
genre_counts = df['Genre'].value_counts()
fiction_count = genre_counts.get('Fiction', 0)
nonfiction_count = genre_counts.get('Non Fiction', 0)

# Overall averages
avg_rating = df['User Rating'].mean()
avg_price = df['Price'].mean()
avg_reviews = df['Reviews'].mean()

# Fiction stats
fiction_df = df[df['Genre'] == 'Fiction']
fiction_avg_rating = fiction_df['User Rating'].mean()
fiction_avg_price = fiction_df['Price'].mean()
fiction_avg_reviews = fiction_df['Reviews'].mean()

# Non-Fiction stats
nonfiction_df = df[df['Genre'] == 'Non Fiction']
nonfiction_avg_rating = nonfiction_df['User Rating'].mean()
nonfiction_avg_price = nonfiction_df['Price'].mean()
nonfiction_avg_reviews = nonfiction_df['Reviews'].mean()

# Pearson correlation coefficient
pearson_corr = df['Price'].corr(df['User Rating'])

# Year-over-year stats
yearly_stats = df.groupby('Year').agg({
    'User Rating': 'mean',
    'Price': 'mean',
    'Reviews': 'mean',
    'Name': 'count'
}).rename(columns={'Name': 'Book Count'}).reset_index()

yearly_fiction = fiction_df.groupby('Year').agg({
    'User Rating': 'mean',
    'Price': 'mean'
}).reset_index()
yearly_fiction.columns = ['Year', 'Fiction_Rating', 'Fiction_Price']

yearly_nonfiction = nonfiction_df.groupby('Year').agg({
    'User Rating': 'mean',
    'Price': 'mean'
}).reset_index()
yearly_nonfiction.columns = ['Year', 'Nonfiction_Rating', 'Nonfiction_Price']

yearly_combined = yearly_stats.merge(yearly_fiction, on='Year').merge(yearly_nonfiction, on='Year')

# Top authors by bestseller frequency
author_counts = df['Author'].value_counts().head(15)
top_authors_data = []
for author, count in author_counts.items():
