def generate_line_chart_svg(data_points, width=600, height=300, title="", x_label="", y_label="", colors=None):
    """Generate SVG line chart"""
    if not data_points:
        return ""

    padding = {'top': 30, 'right': 30, 'bottom': 50, 'left': 60}
    chart_width = width - padding['left'] - padding['right']
    chart_height = height - padding['top'] - padding['bottom']

    # Extract data
    all_values = []
    all_labels = []
    for series in data_points:
        all_values.extend(series.get('values', []))
        all_labels.extend(series.get('labels', []))

    if not all_values:
        return ""

    min_val = min(all_values)
    max_val = max(all_values)
    val_range = max_val - min_val if max_val != min_val else 1

    # Generate paths for each series
    paths = ""
    dots = ""
    legend_items = ""

    for idx, series in enumerate(data_points):
        values = series.get('values', [])
        labels = series.get('labels', [])
        color = (colors and colors[idx]) or f"hsl({idx * 120}, 70%, 50%)"

        if not values:
            continue

        points = []
        for i, val in enumerate(values):
            x = padding['left'] + (i / (len(values) - 1)) * chart_width if len(values) > 1 else padding['left'] + chart_width / 2
            y = padding['top'] + (1 - (val - min_val) / val_range) * chart_height
            points.append(f"{x:.1f},{y:.1f}")

        if points:
            paths += f'<polyline points="{" ".join(points)}" fill="none" stroke="{color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>'
            for i, val in enumerate(values):
                x = padding['left'] + (i / (len(values) - 1)) * chart_width if len(values) > 1 else padding['left'] + chart_width / 2
                y = padding['top'] + (1 - (val - min_val) / val_range) * chart_height
                dots += f'<circle cx="{x:.1f}" cy="{y:.1f}" r="4" fill="{color}"/>'

        legend_items += f'<rect x="{width - 120}" y="{padding['top'] + idx * 25}" width="15" height="15" fill="{color}"/><text x="{width - 100}" y="{padding['top'] + idx * 25 + 12}" font-size="12">{series.get("name", "")}</text>'

    # X-axis labels
    x_labels = ""
    label_values = labels
    for i, label in enumerate(label_values):
        x = padding['left'] + (i / (len(label_values) - 1)) * chart_width if len(label_values) > 1 else padding['left'] + chart_width / 2
        x_labels += f'<text x="{x:.1f}" y="{height - 15}" font-size="11" text-anchor="middle">{label}</text>'

    # Y-axis labels
    y_labels = ""
    for i in range(5):
        val = min_val + (val_range * i / 4)
        y = padding['top'] + (1 - i / 4) * chart_height
        y_labels += f'<text x="{padding['left'] - 10}" y="{y + 4}" font-size="11" text-anchor="end">{val:.2f}</text>'

    svg = f'''<svg width="{width}" height="{height}" viewBox="0 0 {width} {height}">
        <style>
            text {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; fill: #555; }}
        </style>
        <line x1="{padding['left']}" y1="{padding['top']}" x2="{padding['left']}" y2="{height - padding['bottom']}" stroke="#ddd"/>
        <line x1="{padding['left']}" y1="{height - padding['bottom']}" x2="{width - padding['right']}" y2="{height - padding['bottom']}" stroke="#ddd"/>
        {y_labels}
        {x_labels}
        {paths}
        {dots}
        {legend_items}
        <text x="{width/2}" y="20" font-size="14" font-weight="600" text-anchor="middle">{title}</text>
        <text x="{width/2}" y="{height - 5}" font-size="11" text-anchor="middle">{x_label}</text>
    </svg>'''

    return svg

