        val = min_y + (y_range * i / 4)
        y = height - padding['bottom'] - (i / 4) * chart_height
        y_labels += f'<text x="{padding['left'] - 10}" y="{y + 4}" font-size="11" text-anchor="end">{val:.1f}</text>'

    # Legend
    legend = f'''<rect x="{width - 150}" y="{padding['top']}" width="15" height="15" fill="#3498db"/><text x="{width - 130}" y="{padding['top'] + 12}" font-size="12">Fiction</text>
    <rect x="{width - 150}" y="{padding['top'] + 22}" width="15" height="15" fill="#e74c3c"/><text x="{width - 130}" y="{padding['top'] + 34}" font-size="12">Non-Fiction</text>'''

    svg = f'''<svg width="{width}" height="{height}" viewBox="0 0 {width} {height}">
        <style>
