        {y_labels}
        {x_labels}
        {fiction_html}
        {nonfiction_html}
        {legend}
        <text x="{width/2}" y="22" font-size="14" font-weight="600" text-anchor="middle">{title}</text>
        <text x="{width/2}" y="{height - 8}" font-size="11" text-anchor="middle">{x_label}</text>
        <text x="18" y="{height/2}" font-size="11" text-anchor="middle" transform="rotate(-90, 18, {height/2})">{y_label}</text>
    </svg>'''

    return svg

def generate_bar_chart_svg(data, width=500, height=300, title="", horizontal=False):
    """Generate SVG bar chart"""
    padding = {'top': 40, 'right': 30, 'bottom': 60, 'left': 60}
    chart_width = width - padding['left'] - padding['right']
    chart_height = height - padding['top'] - padding['bottom']

    n_bars = len(data)
    bar_width = chart_width / n_bars * 0.7
    bar_gap = chart_width / n_bars * 0.3

    max_val = max([d['value'] for d in data]) if data else 1

    bars = ""
    labels = ""
    values_text = ""

    for i, d in enumerate(data):
        if horizontal:
            bar_height = d['value'] / max_val * chart_height
            x = padding['left']
            y = padding['top'] + i * (chart_height / n_bars) + bar_gap/2
            bars += f'<rect x="{x}" y="{y}" width="{bar_height}" height="{bar_width}" fill="{d.get("color", "#3498db")}" rx="3"/>'
            labels += f'<text x="{x - 10}" y="{y + bar_width/2 + 4}" font-size="11" text-anchor="end">{d["label"]}</text>'
            values_text += f'<text x="{x + bar_height + 5}" y="{y + bar_width/2 + 4}" font-size="11">{d["value"]:.2f}</text>'
        else:
            bar_height = d['value'] / max_val * chart_height
            x = padding['left'] + i * (chart_width / n_bars) + bar_gap/2
            y = height - padding['bottom'] - bar_height
            bars += f'<rect x="{x}" y="{y}" width="{bar_width}" height="{bar_height}" fill="{d.get("color", "#3498db")}" rx="3"/>'
            labels += f'<text x="{x + bar_width/2}" y="{height - 30}" font-size="11" text-anchor="middle">{d["label"]}</text>'
            values_text += f'<text x="{x + bar_width/2}" y="{y - 5}" font-size="11" text-anchor="middle">{d["value"]:.2f}</text>'

    svg = f'''<svg width="{width}" height="{height}" viewBox="0 0 {width} {height}">
        <style>
            text {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; fill: #555; }}
